def the_sons_and_the_cuttings(case, data):
    """F1 — Deut 14:1-2 — THE LINE sons_and_mourning_declared writing cuttings_for_the_dead_barred (a BLOCK — the cut and the factions from one word; the baldness by the analogy run both ways with the priests' 21:5: the whole head, per spot, per soul; 'for the dead' the condition); the sonship's arms (96:9; Kiddushin 36a:11-14); the frontlets' place from the baldness (36a:10); 14:2 the ground — 7:6 by CALL, treasured_people unmoved"""
    del P_[:]
    ask = case['ask']
    if ask == 'the_sonships_arms':
        ink('14:1', '"SONS YOU ARE to the LORD your God" — the clause %s (one seat); Exodus 4:22\'s "My son, My firstborn" %s; the first-person plural in the chapter %s (none); Israel named %s' % (P('בנים', 'אתם', 'ליהוה'), P('בני', 'בכרי'), [v for v in range(1, 30) if any(m and re.search(r'1c[sp]', m) and m.startswith('HV') for _, m in by[('Deut', 14, v)])], [v for v in range(1, 30) if 'ישראל' in W14(v)]))
        move('the Sifrei 96:9 (read whole at the reading); Kiddushin 36a:11-14 (read whole at the docket); Avot 3:14 (the link row); cold_run_seven_nations (CALL) — SN.the_holy_people(chose_you) = %s' % (str(V(SN_CHOSE))[:60],), "THE SONSHIP TWO ARMS — R. Yehuda: if you behave as sons you are sons, if not you are not; R. Meir: either way you are sons, by four verses ('foolish sons', 'sons in whom is no faith', 'a seed of evildoers, sons who corrupt', 'it shall be said to them: sons of the living God' — Kiddushin 36a:12-14; Hosea 2:1 the Sifrei's proof); 'beloved are Israel, called sons of the Omnipresent' (Avot 3:14) — the arms recorded, no parameter: a DATA row")
        dat('the sonship\'s arms a DATA row (the_sonships_arms — R. Yehuda conditional / R. Meir either way; the four verses); the exam\'s person the son who does not act as a son — R. Meir\'s arm: accepted (a son either way)')
        return out("the sonship's arms (14:1) — R. Yehuda: sons when you act as sons; R. Meir: sons either way, by four verses (the Sifrei 96:9; Kiddushin 36a:11-14; Avot 3:14): the son who does not act as a son accepted on R. Meir's arm", ['accepted'])
    if ask == 'the_cut_and_the_factions':
        ink('14:1', '"YOU SHALL NOT CUT YOURSELVES" — the token %s (the reflexive, one seat in the Torah; the root\'s eight seats in the Bible %s — 1 Kings 18:28 Baal\'s prophets the first); "for the dead" %s (14:1, 26:14 in the book)' % (P('לא', 'תתגדדו'), [s for s, x, m in LEMT('1413')], U('למת')))
        move('the Sifrei 96:10-11 (read whole at the reading); Yevamot 13b:17-18, 14a:6-8 (read whole at the docket); cold_run_holiness_b (CALL) — HB.body(gash_for_dead) = %s; HB.body(all_at_once) = %s' % (V(HB_GASH), V(HB_ONCE)), "THE CUT AND THE FACTIONS FROM ONE WORD — the plain sense the mourners' cutting as Baal's prophets cut themselves (96:11; 1 Kings 18:28); THE SECOND READING 'lo titgodedu' (you shall not cut yourselves) as 'do not make yourselves factions' (96:10; Yevamot 13b:17-18 — two conclusions from one word): two courts in one town ruling differently the prohibition (Abaye, 14a:6), one court split (Rava, 14a:7); the places' customs no factions — R. Yosei HaGelili's locale ate fowl in milk (14a:8); Leviticus 19:28's 'a gash for a soul' the kin by CALL — for the dead only (the fallen house excluded)")
        dat('THE WRITE cuttings_for_the_dead_barred — a BLOCK on israel_people at the counter\'s day %s (DF2, DF4): NO CELL ANYWHERE held the cutting\'s bar for all Israel (the recon\'s scan; the one database on Israel %r): the code\'s hole compiled; the readback row 14:1 SUPPLIED AS A LAW WITH THE WRITE (the kin by CALL — holiness_b.body, priesthood.family); the two readings inside the value, no parameter' % (CLOCK['counter'], FOOD_SCAN))
        return out("the cut and the factions (14:1) — the mourners' cutting barred (the plain sense — Baal's prophets 1 Kings 18:28) and 'no factions' from the same word (the Sifrei 96:10-11; Yevamot 13b:17-18; 14a:6-7 two courts / one court split): THE WRITE cuttings_for_the_dead_barred — a BLOCK on Israel at the chapter's own day; the readback row 14:1 SUPPLIED AS A LAW with its write", ['cuttings_for_the_dead_barred'])
    if ask == 'the_mourner_who_cuts':
        ink('14:1', '"you shall not cut yourselves" — the negation pair in the verse %s; the reflexive stem %s' % ([x for x in W14(1) if x in NEG], [(x, m) for x, m in by[('Deut', 14, 1)] if x == 'תתגדדו']))
        move('Mishnah Makkot 3:5 (read whole at the docket); Makkot 20b:11, 21a:1 (read whole at the docket); cold_run_holiness_b (CALL) — HB.body(gash_for_dead) = %s' % (V(HB_GASH),), "THE MOURNER WHO CUTS HIMSELF IS FLOGGED — Mishnah Makkot 3:5: one who makes a cut for the dead; ONE CUT FOR FIVE DEAD, FIVE CUTS FOR ONE DEAD — liable for each (21a:1; 20b:11 the count per soul and per cut); the gash 'for a soul' (Leviticus 19:28 by CALL — for the dead only)")
        dat('the exam\'s person the mourner who cuts himself for the dead — LASHES (Mishnah Makkot 3:5); the count per cut and per soul a DATA row')
        return out("the mourner who cuts himself (14:1) — flogged (Mishnah Makkot 3:5; one cut for five dead, five cuts for one dead — each liable, Makkot 21a:1): lashes", ['lashes'])
    if ask == 'the_baldness_both_ways':
        ink('14:1', '"NOR MAKE BALDNESS BETWEEN YOUR EYES for the dead" — "baldness between your eyes" %s; the root in the Torah %s (14:1 and the priests\' 21:5 alone); "between your eyes" (pl.) %s, (sg.) %s — the frontlets\' clause' % (P('קרחה', 'בין', 'עיניכם'), [s for s, _, _ in LEMT('7144', books=T)], P('בין', 'עיניכם'), P('בין', 'עיניך')))
        move('the Sifrei 96:12 (read whole at the reading); Makkot 20a:12-14 and Kiddushin 36a:6-8 (read whole at the docket); cold_run_priesthood (CALL) — PR.family(marks) = %s; PR.family(corners) = %s' % (V(PR_MARKS), V(PR_CORNERS)), "THE ANALOGY RUN BOTH WAYS (I2, checked in MIDDOT.md — 'korcha' (baldness) one word at two seats, two conclusions): from the priests' 21:5 'on their head' to Israel — THE WHOLE HEAD, not only between the eyes, and each bald spot its own liability (Makkot 20a:12-14; Kiddushin 36a:6-8); from Israel's 14:1 to the priests — 'FOR THE DEAD' the condition (the priests' verse says none); the priests' cell already per spot and the whole head (priesthood.family by CALL: baldness per_spot_whole_head)")
        dat('the baldness both ways a DATA row (the_baldness_both_ways — I2 at two seats: Makkot 20a:14; Kiddushin 36a:7-8); the exam\'s person the one who makes a bald spot behind his ear — the whole head: LASHES')
        return out("the baldness both ways (14:1) — 'korcha' (baldness) at 14:1 and 21:5 alone: the whole head and each spot to Israel, 'for the dead' to the priests (the Sifrei 96:12; Makkot 20a:12-14; Kiddushin 36a:6-8; priesthood.family by CALL): the one who makes a bald spot behind his ear lashed", ['lashes'])
    if ask == 'the_measure_and_the_count':
        ink('14:1', '"baldness" — the noun\'s eleven seats in the Bible %d; Leviticus 21:5\'s "baldness on their head" %s' % (len(LEMT('7144')), P('קרחה', 'בראשם')))
        move('Makkot 20b:2-3, 20b:11, 21a:1; Shabbat 94b:8; Mishnah Makkot 3:5 (read whole at the docket)', "THE MEASURE THREE WAYS — a bean's bulk (Rav Huna), enough for the skin to show (R. Yochanan), two hairs (a baraita; Shabbat 94b:8); THE COUNT — five bald spots for one dead: five sets of lashes (Mishnah Makkot 3:5; 20b:11); per soul as per spot (21a:1); all at once with one warning: one (holiness_b.body 'all_at_once' by CALL — R. Elazar)")
        dat('the measure and the count a DATA row (the_measure_and_the_count — the bean, visible skin, two hairs; five spots five sets); the exam\'s person the one who makes five bald spots for one dead — five sets: LASHES')
        return out("the measure and the count (14:1) — a bean, visible skin, two hairs (Makkot 20b:2-3); five bald spots for one dead five sets (Mishnah Makkot 3:5; 20b:11; 21a:1 per soul): the one who makes five bald spots for one dead lashed", ['lashes'])
    if ask == 'for_the_dead':
        ink('14:1', '"for the dead" (למת) %s — 14:1 and 26:14\'s "I have not given of it for the dead" in the book' % (U('למת', books=DT),))
        move('Makkot 20b:10 and 21a:3 (read whole at the docket); the Sifrei 96:11', "'FOR THE DEAD' THE CONDITION — one who makes a bald spot for his fallen house or his sunk ship is exempt (Makkot 20b:10); THE CUTTING FOR IDOLATRY BESIDE IT (21a:3 — 'they cut themselves after their manner', Baal's priests: R. Yosei — with an instrument liable, with the hand not; the Sages the reverse for idolatry); the gash 'for a soul' (Leviticus 19:28 — holiness_b by CALL: the fallen house excluded)")
        dat('"for the dead" the condition a DATA row (for_the_dead — Makkot 20b:10; the idolatry cut beside it 21a:3); the exam\'s person the one who cuts himself for his fallen house — EXEMPT')
        return out("for the dead (14:1) — the condition: the one who cuts himself or makes a bald spot for his fallen house exempt (Makkot 20b:10); the cutting for idolatry a bar beside it (21a:3)", ['exempt'])
    if ask == 'the_frontlets_place':
        ink('14:1', '"between your eyes" — the plural clause %s (11:18 the frontlets, 14:1 the baldness), the singular %s (6:8; Exodus 13:9, 13:16)' % (P('בין', 'עיניכם'), P('בין', 'עיניך')))
        move('Kiddushin 36a:10 (read whole at the docket); Menachot 37b:5 (carried)', "THE FRONTLETS' PLACE FROM THE BALDNESS — 'between your eyes' at 14:1 is a place where a bald spot can be made, the top of the head where the hair grows; so the frontlets' 'between your eyes' (6:8, 11:18) is the same place, not the brow (Kiddushin 36a:10 — the analogy of the phrase; Menachot 37b the seat)")
        dat('the frontlets\' place a DATA row (the_frontlets_place — Kiddushin 36a:10: from the baldness to the frontlets); the exam\'s person the scholar who places the frontlets on the hair of the head — accepted')
        return out("the frontlets' place (14:1) — 'between your eyes' a place for a bald spot, the top of the head where the hair grows: the frontlets' seat the same (Kiddushin 36a:10); the scholar who places them on the hair of the head accepted", ['accepted'])
    if ask == 'the_holy_people':
        ink('14:2', '"FOR YOU ARE A HOLY PEOPLE to the LORD your God, and the LORD has chosen you to be His treasured people" — the clause %s (14:2, 14:21, 7:6); the shared run with 7:6 %d of %d tokens; "treasure" in the Bible %s (Exodus 19:5 the first)' % (P('כי', 'עם', 'קדוש', 'אתה', 'ליהוה', 'אלהיך'), TWIN['14:2 vs 7:6'], len(W14(2)), [s for s, _, _ in LEMT('5459')]))
        move('cold_run_seven_nations (CALL) — SN.the_holy_people(holy_people) = %s; the tape (the recon): nations_devoted at Deut 7:1 (israel — FOUND by kind and first verse), covenant_offered at Exod 19:5; the Sifrei 97:1-3' % (str(V(SN_HOLY))[:70],), "THE GROUND, NOT A LAW — 14:2 is 7:6 VERBATIM in kind (eighteen of nineteen tokens): the holiness the reason clause of the cutting's bar and of the carcass's (14:21 says it again, 104:7); treasured_people ON FILE ONCE at Exodus 19:5 (a heaven entry) UNMOVED — no write here; 'sanctify yourself' and 'the holiness that is upon you caused it' (97:1)")
        dat('the holy people a DATA row (the_holy_people — 14:2 = 7:6 eighteen of nineteen; the three seats of the clause); treasured_people ONE UNMOVED (DF5); the readback row 14:2 VERBATIM in kind (nations_devoted Deut 7:1; SN by CALL); the exam\'s person the people chosen from all the peoples — accepted')
        return out("the holy people (14:2) — 7:6 said again (eighteen of nineteen tokens; SN.the_holy_people by CALL; treasured_people at Exod 19:5 unmoved): the ground of the cutting's bar, not a law — no write; the people chosen from all the peoples accepted", ['accepted'])
    return out('no verdict in span', [FX.NONE])


def the_beasts(case, data):
    """F2 — Deut 14:3-8 — THE LINE food_law_declared writing abomination_eating_barred (a BLOCK — the general clause over the beasts, the water and the birds); THE TWIN CHAPTER'S CLASSIFIER BY CALL (shemini.classify — the four the classifier's own exception rows; shemini.touch_effect for 14:8); the chapter's gain: the ten named and no more (80a:13-16), the four closed by 'it' (59a:12-14), the shesua a creature (60b:7), the fetus from 14:6's own words (69a:19-23; 68b:8), the altar's disqualified (Mishnah Temurah 6:1)"""
    del P_[:]
    ask = case['ask']
    if ask == 'the_abomination':
        ink('14:3', '"YOU SHALL NOT EAT ANY ABOMINATION" — the clause %s (one seat); the noun\'s Deuteronomy seats %d (14:3 the chapter\'s one); "the abomination of the LORD your God" %s' % (P('לא', 'תאכל', 'כל', 'תועבה'), len(LEMT('8441', books=DT)), P('תועבת', 'יהוה', 'אלהיך')))
        move('the Sifrei 99:1-2 (read whole at the reading); Chullin 114b:9-10 (read whole at the docket); cold_run_shemini (CALL) — SHM.classify(land, hoof, cud) = %s; SHM.classify(camel) = %s' % (SHM_PURE[0], SHM_CAMEL[0]), "THE GENERAL CLAUSE OVER THE WHOLE LIST — 'any abomination' is WHAT I HAVE MADE ABOMINABLE FOR YOU (99:1-2), not what you abominate: the reach at Chullin 114b:9-10 (the Sages: every prohibition of eating is under 'you shall not eat any abomination'; R. Yishmael's arm); THE TWIN CHAPTER'S CELLS BY CALL — the beasts' two signs, the water's two, the birds by name: the classifier answers the four (impure) and the pure beast (pure)")
        dat('THE WRITE abomination_eating_barred — a BLOCK on israel_people at the counter\'s day %s (DF2, DF4): the general clause over 14:3-20 (the one database on Israel %r); the readback row 14:3 SUPPLIED AS A LAW WITH THE WRITE; the exam\'s rows through forbidden_kind_eaten (shemini\'s case kind REUSED — Makkot 3:2) and food_tithe_case' % (CLOCK['counter'], FOOD_SCAN))
        return out("the abomination (14:3) — 'you shall not eat any abomination' = what I have made abominable for you (the Sifrei 99:1-2; Chullin 114b:9-10): THE WRITE abomination_eating_barred — a BLOCK on Israel over the beasts, the water and the birds, the twin chapter's classifier by CALL; the readback row 14:3 SUPPLIED AS A LAW with its write", ['abomination_eating_barred'])
    if ask == 'the_ten_named':
        ink('14:4-5', '"THIS IS THE BEAST which you may eat: the ox, the sheep and the goat; the hart, the gazelle, the roebuck, the wild goat, the ibex, the antelope and the mountain sheep" — "this is the beast" %s against Leviticus 11:2\'s "this is the living thing" %s; the seven wild beasts\' one kin in the Bible %s (Solomon\'s table); the antelope and the ibex hapax %s %s' % (P('זאת', 'הבהמה', 'אשר', 'תאכלו'), P('זאת', 'החיה', 'אשר', 'תאכלו'), KINC[5], U('אקו', 'ואקו'), U('זמר', 'וזמר')))
        move('the Sifrei 100:1-2 (read whole at the reading); Chullin 80a:13-16 (read whole at the docket); 1 Kings 5:3 (the run\'s case outside the tape); cold_run_erection (CALL) — ER.repeats(seh_class) = %s' % (V(ER_SEH),), "THE TEN NAMED AND NO MORE — R. Yitzchak: ten clean animals, three domestic and seven wild (80a:13); 'why list them all?' — THE LIST CLOSED AGAINST PARTICULAR-THEN-GENERAL (80a:14-16 — the names are the whole set, the sign the class; I5 refused); the wild under the beast's name (71a:2; Zevachim 34a:15); 'seh' (a lamb or kid) the paradigm excluding the hybrid (Bava Kamma 77b:13; erection.repeats 'seh_class' by CALL — sheep or goat, any sex, age, blemish)")
        dat('the ten named a DATA row (the_ten_named — Chullin 80a:13-16; Solomon\'s table 1 Kings 5:3 the one kin, 14:5 nowhere else in the Torah); the readback rows 14:4 VARIANT (Leviticus 11:2-3 without the names — SHM by CALL) and 14:5 SUPPLIED (the seven wild beasts); the exam\'s person the one who eats the antelope — accepted (a named clean beast)')
        return out("the ten named (14:4-5) — three domestic and seven wild, and no more (Chullin 80a:13-16 — the list closed; 1 Kings 5:3 the one kin in the Bible); 'seh' the paradigm (Bava Kamma 77b:13; ER.repeats by CALL): the one who eats the antelope accepted", ['accepted'])
    if ask == 'the_two_signs':
        ink('14:6', '"and every beast that parts the hoof and has the hoof cloven in TWO and chews the cud" — the parser\'s [2] %s; the clause shared with Leviticus 11:3 %s; the shared run with 11:3 %d (14:6 is 11:3 with "two hoofs"); "two hoofs" %s' % (PARSED[(14, 6)], P('מפרסת', 'פרסה', 'ושסעת', 'שסע'), TWIN['14:6 vs 11:3'], P('שתי', 'פרסות')))
        move('the Sifrei 98:1 (read whole at the reading); cold_run_shemini (CALL) — SHM.classify(land, hoof, cud) = %s; SHM.classify(swine) = %s; Chullin 59a:1-11 (read whole at the docket)' % (SHM_PURE[0], SHM_SWINE[0]), "THE THREE SIGNS FROM THE THREE CLAUSES (98:1 — parts the hoof, cloven in two, chews the cud: the cleft that goes through, the two hoofs) — THE TWIN CHAPTER'S CELL answers by CALL: hoof AND cud pure, one sign or none impure (the pincer of the four exceptions); the wild beast's horn signs for the fat and the blood (59a:8-11 — branched, rounded, notched)")
        dat('the two signs a DATA row (the_two_signs — 14:6 = 11:3 with "two"; the parser\'s [2]; the three signs 98:1); the readback row 14:6 VARIANT by CALL; the exam\'s person the eater of the ox — accepted (SHM.classify pure)')
        return out("the two signs (14:6) — the hoof parted and cloven in two, the cud chewed (11:3 with 'two' — the parser's [2]; the Sifrei 98:1; SHM.classify by CALL: pure): the eater of the ox accepted", ['accepted'])
    if ask == 'the_four_closed_by_it':
        ink('14:7-8', '"but these you shall not eat … the camel, the hare and the coney … and the swine" — the three folded into one %s (Leviticus 11:4-6 three verses); "it is unclean for you" %s; the shared run 14:7 with 11:4 %d, 14:8 with 11:7 %d' % (P('הגמל', 'ואת', 'הארנבת', 'ואת', 'השפן'), P('טמא', 'הוא', 'לכם'), TWIN['14:7 vs 11:4'], TWIN['14:8 vs 11:7']))
        move('the Sifrei 101:10 (read whole at the reading — I1, checked in MIDDOT.md); Chullin 59a:12, 59a:14 (read whole at the docket); cold_run_shemini (CALL) — SHM.classify(camel) = %s, (hare) = %s, (coney) = %s, (swine) = %s' % (SHM_CAMEL[0], SHM_HARE[0], SHM_CONEY[0], SHM_SWINE[0]), "THE FOUR CLOSED BY 'IT' — the school of R. Yishmael: 'the Ruler of His world knows that there is no other that chews the cud and is unclean but the camel' (59a:12), 'no other that parts the hoof and is unclean but the swine' (59a:14) — the four are the written exception set, THE CLASSIFIER'S OWN EXCEPTION ROWS: the sign the class, the names the exceptions (101:10 — a fortiori: if these with one sign are barred, those with none surely)")
        dat('the four closed by "it" a DATA row (the_four_closed_by_it — 59a:12, 59a:14; 101:10 I1); the readback rows 14:7 VARIANT (11:4-6 folded) and 14:8 VERBATIM in kind (11:7-8) by CALL; the exam\'s person the eater of the camel — LASHES (Makkot 3:2 the eater of the unclean)')
        return out("the four closed by 'it' (14:7-8) — the camel, the hare, the coney, the swine the written exception set: the Ruler of His world knows no other (Chullin 59a:12, 59a:14; the Sifrei 101:10 — I1); SHM.classify by CALL impure: the eater of the camel lashed", ['lashes'])
    if ask == 'the_shesua':
        ink('14:7', '"the cleft one" (השסועה) %s — the token\'s one seat, the beasts\' list repeated to add it (Chullin 63b:4)' % (U('השסועה', 'שסועה'),))
        move('the Sifrei 98:2 (read whole at the reading); Chullin 60b:7 and 80a:11-12 (read whole at the docket); Niddah 24a:13 (the link row); Tosefta Kilayim 1:9', "THE SHESUA A CREATURE — 'was Moses a hunter or an archer?' (60b:7; Niddah 24a:13): a creature of its own kind with two backs and two spines, not a fetus's malformation; the beasts' list repeated to ADD it (63b:4; Bekhorot 6b:20); THE KOY (a doubtful kind) FOUR WAYS (80a:11-12 — a wild goat, a cross, a kind of its own, the ram of the forest; Tosefta Kilayim 1:9)")
        dat('the shesua a DATA row (the_shesua — 60b:7; the koy four ways 80a:11-12); the exam\'s person the scholar who counts the shesua among the additions — accepted')
        return out("the shesua (14:7) — the cleft one a creature of its own kind, 'was Moses a hunter?' (Chullin 60b:7; Niddah 24a:13); the list repeated to add it (63b:4); the koy four ways (80a:11-12): the scholar who counts it among the additions accepted", ['accepted'])
    if ask == 'the_fetus':
        ink('14:6', '"among the beasts (בבהמה), IT you may eat" — "in the beast" %s; "and every" %s; "it" (אתה) %s: the three words the Gemara reads' % ([(v, x) for v in (6,) for x in W14(v) if x == 'בבהמה'], [x for x in W14(6) if x == 'וכל'], [x for x in W14(6) if x == 'אתה']))
        move('Chullin 68a:1, 69a:19-23, 68b:8, 77a:11-15 (read whole at the docket); Mishnah Chullin 4:1', "THE FETUS FROM 14:6'S OWN WORDS — 'in the animal you may eat': the fetus inside its slaughtered mother permitted by its mother's slaughter (69a:19); 'and every' includes the placenta (69a:22; 77a:11-15); 'it' the limit (69a:23); 'hoof / hooves' the cut's place (68b:8) — THE UNCLOVEN FETUS permitted inside its mother (the mother's slaughter its own); the limb that went out and returned — Rav bars it by 'flesh in the field, torn' (Exodus 22:30 — 68a:3-68b:14), R. Yochanan permits (68b:10)")
        dat('the fetus a DATA row (the_fetus — 69a:19-23; 68b:8 the uncloven fetus; the limb\'s dispute Rav / R. Yochanan); the exam\'s person the one who eats the uncloven fetus found inside its slaughtered mother — accepted')
        return out("the fetus (14:6) — 'in the animal', 'and every', 'it' (Chullin 69a:19-23): the fetus permitted by its mother's slaughter, the uncloven fetus inside its mother too (68b:8), the placenta by 'every' (77a:11-15); the limb out and back disputed (68a:3-68b:14): the one who eats the uncloven fetus inside its slaughtered mother accepted", ['accepted'])
    if ask == 'the_limb_extended':
        ink('14:6', '"it you may eat" — the limit; Exodus 22:30\'s "flesh in the field, torn" %s (the four torn seats %s)' % (words('Exod', 22, 30)[-4:], V(OR_SEATS)))
        move('Chullin 68a:3-68b:14 and 68b:10 (read whole at the docket); cold_run_ordinances (CALL) — OR.torn(field_common_case) = %s' % (V(OR_FIELD),), "THE LIMB EXTENDED AND RETURNED — Rav: the limb that went out of the womb and came back is barred by 'flesh in the field, torn' (once outside its place it is 'in the field' — Ulla's refutation of the counter-cases, 68a:3-68b:14); R. Yochanan: permitted (68b:10); the limb that stays out barred by all")
        dat('the limb extended a DATA row (the_limb_extended — Rav / R. Yochanan; ordinances.torn by CALL); the exam\'s person the one who eats the limb that came out and returned — accepted on R. Yochanan\'s arm (Rav\'s recorded)')
        return out("the limb extended (14:6) — out of the womb and back: Rav bars it by 'flesh in the field, torn' (Chullin 68a:3-68b:14; OR.torn by CALL), R. Yochanan permits (68b:10): the one who eats the limb that came out and returned accepted on R. Yochanan's arm", ['accepted'])
    if ask == 'the_altars_disqualified':
        ink('14:4', '"the ox, the sheep and the goat" — the three domestic %s; the altar\'s names' % (P('שור', 'שה', 'כשבים', 'ושה', 'עזים'),))
        move('the Sifrei 101:1-9 (read whole at the reading); Mishnah Temurah 6:1 (read whole at the docket); cold_run_temurah (CALL) — TM.tithe(herd_with_flock) = %s' % (V(TM_HERD),), "THE ALTAR'S DISQUALIFIED BY THE NAMES — 'the ox' excludes the animal that killed a man, 'the sheep' the one worshipped, 'the goat' the hire of a harlot and the price of a dog (101:1-9 — each name a license and a bar); Mishnah Temurah 6:1: the animal that copulated with a man, the set-aside, the worshipped, the hire, the price, the hybrid, the torn, the caesarean — barred from the altar")
        dat('the altar\'s disqualified a DATA row (the_altars_disqualified — 101:1-9; Mishnah Temurah 6:1); the exam\'s person the one who offers the hire of a harlot — barred_from_it')
        return out("the altar's disqualified (14:4) — the names license the table and bar the altar's disqualified: the killer, the worshipped, the hire, the price (the Sifrei 101:1-9; Mishnah Temurah 6:1): the one who offers the hire of a harlot barred from it", ['barred_from_it'])
    if ask == 'the_carcass_touched':
        ink('14:8', '"of their flesh you shall not eat, AND THEIR CARCASS YOU SHALL NOT TOUCH" — the clause shared with Leviticus 11:8 (the shared run %d); "carcass" in Deuteronomy %s' % (TWIN['14:8 vs 11:7'], [s for s, x, _ in LEMT('5038', books=T) if s.startswith('Deut')]))
        move('cold_run_shemini (CALL) — SHM.touch_effect(touch_carcass) = %s; SHM.touch_effect(carry_carcass) = %s; the Sifrei 102:1' % (SHM_TOUCH[0], SHM_CARRY[0]), "THE TOUCH BY CALL — Leviticus 11:24's eightfold clause: the toucher of the carcass impure until evening, the carrier washes and waits (shemini.touch_effect); 102:1 the touch's reach (on the festival — the Sifrei's condition)")
        dat('the readback row 14:8 VERBATIM in kind (11:7-8) by CALL; the exam\'s person the one who touches the swine\'s carcass — impure_until_evening')
        return out("the carcass touched (14:8) — 'their carcass you shall not touch' 11:8's clause: the toucher impure until evening (shemini.touch_effect by CALL — Leviticus 11:24)", ['impure_until_evening'])
    return out('no verdict in span', [FX.NONE])


def the_water_and_the_birds(case, data):
    """F3 — Deut 14:9-20 — the water's two signs (14:9-10 — 14:9 read through its twin, Chullin 66b:6-7: NOT CITED BY ANYONE); THE PERMISSION FOR THE CLEAN BIRD Leviticus lacks (14:11, 14:20 — 103:1, 103:9) with THE PARAMETER the_birds_signs in three layers (Mishnah Chullin 3:6; Chullin 61a:1; 62a:4; 63b:11 — the code/data separation law's own case); the two lists counted (63a:17-63b:2); the eggs (64a:5, 64b:4); the locusts absent here (Leviticus 11:21-22 by CALL); the swarming fowl (14:19)"""
    del P_[:]
    ask = case['ask']
    if ask == 'fins_and_scales':
        ink('14:9-10', '"THESE YOU MAY EAT of all that are in the waters: all that have FINS AND SCALES you may eat; and whatever has not fins and scales you shall not eat" — "fins and scales" %s; 14:9 twelve of Leviticus 11:9\'s twelve %d (the seas and the rivers dropped); "unclean for you" for "detestable" at 14:10' % (P('סנפיר', 'וקשקשת'), TWIN['14:9 vs 11:9']))
        move('Chullin 66a:1-66b:12 (read whole at the docket — 14:9 NOT CITED BY ANYONE, read through its twin 66b:6-7); cold_run_shemini (CALL) — SHM.classify(water, fin, scale) = %s; SHM.classify(water, no fin) = %s' % (SHM_FISH[0], SHM_NOFIN[0]), "THE WATER'S TWO SIGNS BY CALL — fins and scales pure, either lacking impure (Leviticus 11:9-12; the classifier's water keys 'fin' and 'scale' — the print's first dict with 'fins' returned impure, the source read); 14:9 THROUGH ITS TWIN — 'these you may eat' a command and 'you shall not eat' a ban: the permission's reach vessels, pits, ditches and caves (66b:6-7); all that has scales has fins (66b:1-5 — Mishnah Niddah 6:9)")
        dat('fins and scales a DATA row (fins_and_scales — 14:9 twelve of twelve; the verse no one cites read through its twin); the readback rows 14:9, 14:10 VARIANT by CALL; the exam\'s person the eater of the fish with fins and scales — accepted')
        return out("fins and scales (14:9-10) — 11:9-12 said again with the seas and the rivers dropped (SHM.classify by CALL: pure); 14:9 read through its twin, Chullin 66b:6-7 (vessels, pits, ditches and caves): the eater of the fish with fins and scales accepted", ['accepted'])
    if ask == 'the_fish_without_scales':
        ink('14:10', '"and whatever has not fins and scales YOU SHALL NOT EAT; it is unclean for you" — the negation %s; "unclean for you" %s' % ([x for x in W14(10) if x in NEG], [x for x in W14(10) if x in ('טמא', 'טמאים', 'הטמא')]))
        move('cold_run_shemini (CALL) — SHM.classify(water, fin, no scale) = %s; Mishnah Makkot 3:2 (the link row — the eater of the unclean fish); Chullin 66b:1-5' % (SHM_NOSCALE[0],), "THE FISH WITHOUT SCALES BARRED — one sign or none impure (SHM by CALL); the eater of an unclean fish among the flogged (Mishnah Makkot 3:2); a fish with scales and no fins does not exist (66b:1-5) — the ban's live case the eel")
        dat('the exam\'s person the eater of the eel (no scales) — LASHES (Makkot 3:2)')
        return out("the fish without scales (14:10) — 'whatever has not fins and scales you shall not eat' (SHM.classify by CALL: impure; Mishnah Makkot 3:2): the eater of the eel lashed", ['lashes'])
    if ask == 'the_permission':
        ink('14:11, 14:20', '"EVERY CLEAN BIRD YOU MAY EAT" %s and "every clean fowl you may eat" %s — the two permissions; Leviticus 11:13\'s "these you shall detest of the fowl" %s (no permission there); "after its kind" four times here %d and four times in 11:13-19 %d' % (P('כל', 'צפור', 'טהרה', 'תאכלו'), P('כל', 'עוף', 'טהור', 'תאכלו'), P('ואת', 'אלה', 'תשקצו', 'מן', 'העוף'), sum(1 for v in range(12, 19) for x in W14(v) if x.startswith('למינ')), sum(1 for v in range(13, 20) for x in words('Lev', 11, v) if x.startswith('למינ'))))
        move('the Sifrei 103:1, 103:9 (read whole at the reading); cold_run_shemini (CALL) — SHM.classify(bird: extra toe, crop, peelable gizzard) = %s; SHM.classify(bird named in the list) = %s' % (SHM_DOVE[0], SHM_EAGLE[0]), "THE PERMISSION LEVITICUS LACKS — 'every clean bird you may eat' (14:11) and 'every clean fowl you may eat' (14:20): Leviticus 11 names the unclean and permits nothing; 103:1 the permission's seat, 103:9 the second — the lexicon rule 'bird' = clean (98:3; 228:5 the bird's nest); the classifier's bird branch a blacklist by name and the Sages' signs (SHM by CALL: the dove pure, the eagle impure)")
        dat('the permission a DATA row (the_permission — 14:11, 14:20 the two seats; Leviticus none); the readback rows 14:11 and 14:20 SUPPLIED (the permission Leviticus lacks; the_birds_signs the parameter); the exam\'s person the eater of the dove — accepted')
        return out("the permission (14:11, 14:20) — 'every clean bird you may eat', the permission Leviticus 11 lacks (the Sifrei 103:1, 103:9; SHM.classify by CALL — the dove pure): the eater of the dove accepted; the readback rows SUPPLIED", ['accepted'])
    if ask == 'the_birds_signs':
        ink('14:11', '"every CLEAN bird" — "clean" in the chapter %s; the twenty-one unclean named 14:12-18; no sign of a clean bird in the ink' % ({v: [x for x in W14(v) if x in ('טהור', 'טהרה')] for v in range(1, 30) if any(x in ('טהור', 'טהרה') for x in W14(v))},))
        move('Mishnah Chullin 3:6 at 59a:6; Chullin 61a:1-61b:7, 62a:1-4, 62b:5, 63b:11 (read whole at the docket); Tosefta Bekhorot 1:5; the parameter the_birds_signs = %s' % (sorted(BIRDS),), "THE BIRDS' SIGNS THE SAGES' TEACHING — THREE LAYERS (the parameter): the four signs (an extra toe, a crop, a gizzard that peels by hand, not a clawer — Mishnah Chullin 3:6) derived from the two poles, the nesher (the great vulture) with none and the dove with all four (61a:1 — Abaye: the signs' explanation is not in the Torah; the ladder to one sign 61a:2-61b:7; the twenty-four with their signs 61b:6); THE RULING one sign and no clawing (Ameimar, 62a:4) with the knowledge condition (62a:1 — for one who knows the twenty-four); THE TRADITION ARM — a clean bird eaten by tradition, the hunter believed (R. Yitzchak, 63b:11; Tosefta Bekhorot 1:5): THE CODE/DATA SEPARATION LAW'S OWN CASE — the value DATA, read, never coded")
        dat('THE PARAMETER the_birds_signs on file (DF6 — calendar_parameters.yaml, three layers: %s); the exam\'s person the hunter who brings a bird by tradition — accepted (the tradition arm, 63b:11)' % (sorted(BIRDS),))
        return out("the birds' signs (14:11) — the Sages' teaching in three layers: the four signs from the two poles (Mishnah Chullin 3:6; Chullin 61a:1), one sign and no clawing with the knowledge condition (62a:1-4), the tradition arm (63b:11): THE PARAMETER the_birds_signs; the hunter who brings a bird by tradition accepted", ['accepted'])
    if ask == 'the_clawer':
        ink('14:12', '"and these are they of which you shall not eat: the eagle, the vulture and the osprey" — the list\'s head %s; 11:13\'s three the same' % (P('וזה', 'אשר', 'לא', 'תאכלו', 'מהם'),))
        move('Chullin 59a:6, 62a:4 (read whole at the docket); cold_run_shemini (CALL) — SHM.classify(bird: claws and eats) = %s; SHM.classify(bird unknown) = %s' % (SHM_CLAWER[0], SHM_UNKNOWN[0]), "THE CLAWER IMPURE — 'every clawer impure' (Mishnah Chullin 3:6; the classifier's Sages' layer by CALL); one sign WITHOUT the clawing's absence does not clear (62a:4 — Ameimar's proviso); the unknown bird 'unresolved, check tradition' (SHM's own label — the tradition arm)")
        dat('the exam\'s person the one who eats a bird with one sign that claws — LASHES (the ruling\'s proviso, 62a:4; Makkot 3:2)')
        return out("the clawer (14:12) — one sign clears only where the bird does not claw (Chullin 62a:4; Mishnah Chullin 3:6 — SHM.classify by CALL: the clawer impure): the one who eats a bird with one sign that claws lashed", ['lashes'])
    if ask == 'the_two_lists':
        ink('14:12-18', '"the glede (הראה), the kite and the falcon after its kind" — the ra\'ah\'s seats %s against Leviticus 11:14\'s da\'ah %s (resh for dalet, one letter); 14:13 %s against 11:14 %s; 14:15 = 11:16 to the letter %s; 14:16-17 against 11:17-18\'s order' % (U('והראה'), U('והדאה', 'הדאה', 'דאה', 'דיה', 'והדיה', 'הדיה'), W14(13), words('Lev', 11, 14), TWIN['14:15 == 11:16']))
        move('Chullin 63a:17-63b:2, 63b:3-9; Bekhorot 6b:20 (read whole at the docket); the Sifrei 98:5-6, 103:3-4 (read whole at the reading)', "THE TWO LISTS COUNTED AT THEIR SEAT — Leviticus twenty, Deuteronomy twenty-one; the da'ah (Leviticus's kite) and the ra'ah (Deuteronomy's) ONE BIRD, the ayya and the dayya (the falcon and the glede) one — TWENTY-FOUR unclean kinds (63a:17-63b:2; both names written against the disputant, 63b:3; R. Abbahu's twenty-three 63b:5-7); THE COUNTING RULE — the smaller set is listed (63b:9); the beasts' list repeated to ADD the shesua, the birds' only to EXPLAIN the ra'ah (63b:4; Bekhorot 6b:20): the reading's diff confirmed by the Gemara's own arithmetic; the list carried by its head (103:3-4 — I2)")
        dat('the two lists a DATA row (the_two_lists — twenty, twenty-one, twenty-four; the ra\'ah\'s resh; 14:15 = 11:16 to the letter — DF8); the readback rows 14:12-18 VARIANT and VERBATIM in kind by CALL; the exam\'s person the scholar who counts twenty-four — accepted')
        return out("the two lists (14:12-18) — Leviticus twenty, Deuteronomy twenty-one, the da'ah and the ra'ah one bird, the ayya and the dayya one: twenty-four (Chullin 63a:17-63b:2); the beasts' list adds, the birds' explains (63b:4): the scholar who counts twenty-four accepted", ['accepted'])
    if ask == 'the_eggs':
        ink('14:15', '"and the ostrich" (בת היענה — the daughter of the ostrich) %s' % ([x for x in W14(15) if x in ('בת', 'היענה')],))
        move('Chullin 64a:5, 64b:4 (read whole at the docket)', "THE EGGS' SIGNS NOT TORAH LAW — the signs of eggs (a rounded end, the yolk within the white) are the Sages' (64a:5); THE UNCLEAN BIRD'S EGG barred from the list's own name — 'the daughter of the ostrich' (64b:4): the egg of an unclean bird is barred as the bird")
        dat('the eggs a DATA row (the_eggs — 64a:5 not Torah law; 64b:4 the daughter of the ostrich); the exam\'s person the eater of the ostrich\'s egg — barred_from_it')
        return out("the eggs (14:15) — the eggs' signs the Sages' (Chullin 64a:5); the unclean bird's egg barred from 'the daughter of the ostrich' (64b:4): the eater of the ostrich's egg barred from it", ['barred_from_it'])
    if ask == 'the_locusts_absent':
        ink('14:19-20', '"and every swarming winged thing is unclean for you; they shall not be eaten" — %s; no locust in the chapter %s (Leviticus 11:22\'s "the locust" %s)' % (P('וכל', 'שרץ', 'העוף', 'טמא', 'הוא', 'לכם'), not any('ארבה' in x for v in range(1, 30) for x in W14(v)), 'הארבה' in words('Lev', 11, 22)))
        move('the Sifrei 103:10 (read whole at the reading); Chullin 65a:1-66a:9 (read whole at the docket); cold_run_shemini (CALL) — SHM.classify(locust, the four signs) = %s' % (SHM_LOCUST[0],), "THE LOCUSTS ABSENT HERE — Leviticus 11:21-22's permission (the four signs: four legs, four wings, jumping joints, wings covering most — Mishnah Chullin 3:7; Chullin 65a-66a) stands by CALL; 103:10 'the frames' — 14:19's 'every swarming winged thing' and 14:20's 'every clean fowl' frame the permission; the classifier's locust branch pure")
        dat('the locusts absent a DATA row (the_locusts_absent — 103:10 the frames; Leviticus 11:21-22 by CALL); the readback row 14:19 VARIANT by CALL; the exam\'s person the eater of the locust with the four signs — accepted')
        return out("the locusts absent (14:19-20) — Leviticus 11:21-22's permission by CALL (SHM.classify: pure — the four signs, Mishnah Chullin 3:7); 14:19 and 14:20 the frames (the Sifrei 103:10): the eater of the locust with the four signs accepted", ['accepted'])
    if ask == 'the_swarming_fowl':
        ink('14:19', '"every swarming winged thing is UNCLEAN for you; THEY SHALL NOT BE EATEN" — "unclean" for Leviticus 11:20\'s "detestable"; the passive %s' % ([(x, m) for x, m in by[('Deut', 14, 19)] if x == 'יאכלו'],))
        move('Chullin 65a:1-10 (read whole at the docket); Mishnah Makkot 3:2 (the link row)', "THE SWARMING FOWL BARRED — the fly, the hornet, the winged swarmer without the locust's signs (65a); the eater among the flogged (Mishnah Makkot 3:2 — the swarmers); 'unclean' for 'detestable' the chapter's word")
        dat('the exam\'s person the eater of the hornet — LASHES (Makkot 3:2)')
        return out("the swarming fowl (14:19) — 'they shall not be eaten': the winged swarmer without the four signs (Chullin 65a; Mishnah Makkot 3:2): the eater of the hornet lashed", ['lashes'])
    return out('no verdict in span', [FX.NONE])

